insert into knowledge_documents (id, restaurant_id, type, title, body, is_published) values
    ('00000000-0000-0000-0000-00000000d001', '00000000-0000-0000-0000-00000000a001', 'history', 'История ресторана',
     'Лавраки открыли в 2009 году братья Яннис и Костас Пападопулос в старом портовом складе квартала Лададика. Склад был такой гулкий, что первый месяц братья переговаривались эхом и путали, кто что заказал. Кирпичные стены и дубовые балки остались с тех времён — по балкам до сих пор видно, где хранили мешки с солью.', true),
    ('00000000-0000-0000-0000-00000000d002', '00000000-0000-0000-0000-00000000a001', 'history', 'Почему «Лавраки»',
     'Лавраки — греческое имя сибаса. Это первая рыба, которую отец братьев продавал на рынке Капани, и первая, которую маленький Яннис уронил в корзину с лимонами. Отец сказал: «Вот так её и подавай — с лимоном». С тех пор лавраки на гриле с лимоном — главное блюдо ресторана.', true),
    ('00000000-0000-0000-0000-00000000d003', '00000000-0000-0000-0000-00000000a001', 'team', 'Братья-основатели и вечный спор',
     'Яннис уверен, что рыбе нужен только лимон. Костас уверен, что только орегано. Спор идёт с 2009 года и официально не решён, поэтому каждая рыба на гриле у нас приходит и с лимоном, и с орегано. Гости иногда голосуют салфетками: белая — за лимон, синяя — за орегано. Счёт ведётся мелом на двери кухни и никогда не сходится.', true),
    ('00000000-0000-0000-0000-00000000d004', '00000000-0000-0000-0000-00000000a001', 'team', 'Шеф Тасос Кукурас',
     'Шеф Тасос — хозяин гриля и обладатель самых пышных усов в Лададике. Он разговаривает с углями и уверен, что угли обижаются, если рыбу перевернуть дважды, поэтому каждую рыбу переворачивает ровно один раз. Когда блюдо удалось особенно, Тасос бьёт половником в медную сковороду над грилем — если услышите гонг, значит, ваша рыба готова.', true),
    ('00000000-0000-0000-0000-00000000d005', '00000000-0000-0000-0000-00000000a001', 'team', 'Бабушка Деспина и тетрадь рецептов',
     'Бабушка Деспина — мама братьев и хранительница рецептов. Все рецепты записаны в толстую тетрадь с кляксами от оливкового масла; тетрадь лежит в сейфе вместе с выручкой, и бабушка считает, что тетрадь ценнее. Каждый новый соус она пробует сама и ставит оценку по своей шкале: «ну такое», «съедобно», «неплохо» и высшая — «можно жениться». В меню попадает только «можно жениться».', true),
    ('00000000-0000-0000-0000-00000000d006', '00000000-0000-0000-0000-00000000a001', 'team', 'Капитан Стелиос, наш рыбак',
     'Капитан Стелиос ловит рыбу в заливе Термаикос на лодке «Упрямая Мария». Каждое утро около шести он гудит в медный рог у причала, и вся кухня бежит встречать улов с ящиками. Стелиос ни разу не опоздал за пятнадцать лет, зато ни разу не сказал заранее, что именно поймал — поэтому рыба дня у нас всегда сюрприз даже для шефа.', true),
    ('00000000-0000-0000-0000-00000000d007', '00000000-0000-0000-0000-00000000a001', 'team', 'Сомелье Ефросинья',
     'Ефросинья подбирает вино по настроению: смотрит, как гость держит меню, и уже знает, белое ему или красное. Тех, кто держит меню обеими руками, она считает людьми серьёзными и несёт ксиномавро. Если сомневаетесь в выборе — просто позовите Ефросинью, это бесплатно, и она ни разу не предложила бокал, который гость не допил.', true),
    ('00000000-0000-0000-0000-00000000d008', '00000000-0000-0000-0000-00000000a001', 'team', 'Кондитер Нефели',
     'Нефели отвечает за десерты и растягивает тесто фило над головой до размеров простыни. Говорят, однажды во время ливня она так укрыла тестом половину веранды, но это не точно. Бугацу, галактобуреко и лукумадес Нефели готовит каждое утро, поэтому вечером десерты иногда заканчиваются — уточняйте у официанта.', true),
    ('00000000-0000-0000-0000-00000000d009', '00000000-0000-0000-0000-00000000a001', 'team', 'Стажёр Мильтос и случайный десерт',
     'Мильтос пришёл на кухню стажёром и за первую неделю уронил сорок две тарелки — счёт висит на стене. Однажды он опрокинул миску тимьянового мёда на йогурт с грецкими орехами, бабушка Деспина попробовала и сказала «можно жениться». Так в меню появился йогурт с мёдом и орехами, а Мильтоса оставили на кухне. Тарелки он роняет до сих пор, но реже.', true),
    ('00000000-0000-0000-0000-00000000d010', '00000000-0000-0000-0000-00000000a001', 'other', 'Рыжий кот Порто, талисман ресторана',
     'Портокалис, для своих Порто, — рыжий кот и талисман Лавраки. Его имя по-гречески значит «апельсин». Порто приплыл в 2015 году на лодке капитана Стелиоса, спрятавшись в ящике с сардинами, и отказался уходить. Живёт на веранде, спит на тёплом навесе над грилем и встречает каждого гостя взглядом ресторанного критика. На кухню Порто не заходит никогда — это правило ресторана.', true),
    ('00000000-0000-0000-0000-00000000d011', '00000000-0000-0000-0000-00000000a001', 'other', 'Утренняя инспекция Порто',
     'Каждое утро, когда капитан Стелиос привозит улов, Порто лично обходит ящики с рыбой. Шеф Тасос утверждает, что если кот отвернулся от ящика — рыбу возвращают в море. Капитан утверждает, что такого не было ни разу. Сам Порто комментариев не даёт. Посмотреть на инспекцию можно с причала около шести утра — сам ресторан в это время закрыт.', true),
    ('00000000-0000-0000-0000-00000000d012', '00000000-0000-0000-0000-00000000a001', 'other', 'Как угостить кота',
     'Кормить Порто со своей тарелки нельзя: соль, специи и соусы коту вредны. Если хочется его угостить, закажите позицию «Рыбка для кота» или «Королевский ужин для кота» — официант вынесет коту угощение без соли на веранду, а вы посмотрите. Весь доход от этих позиций идёт в приют для кошек Салоник. Больше двух угощений в день Порто не положено, даже если он очень просит.', true),
    ('00000000-0000-0000-0000-00000000d013', '00000000-0000-0000-0000-00000000a001', 'other', 'Порто и собаки гостей',
     'С собаками к нам можно только на веранду. Порто относится к собакам свысока — буквально: при виде собаки он забирается на навес и наблюдает оттуда. Конфликтов за всю историю не было ни одного. Если у вас аллергия на кошек, выбирайте зал — Порто туда не заходит.', true),
    ('00000000-0000-0000-0000-00000000d014', '00000000-0000-0000-0000-00000000a001', 'history', 'Старый склад в Лададике',
     'Здание построено в 1890-х как склад соли и пряностей при порте. В зале сохранились чугунные колонны и грузовой крюк под потолком; на крюке теперь висит медная сковорода шефа Тасоса. Пол местами неровный — это не мы криво постелили, это сто тридцать лет истории.', true),
    ('00000000-0000-0000-0000-00000000d015', '00000000-0000-0000-0000-00000000a001', 'history', 'Награды и пресса',
     'Лавраки трижды называли лучшей рыбной таверной Салоник по версии местной газеты. Самой дорогой наградой братья считают медаль «За самый громкий гонг квартала», которую соседи вручили шефу Тасосу в шутку. Медаль висит рядом со счётом разбитых тарелок Мильтоса.', true),
    ('00000000-0000-0000-0000-00000000d016', '00000000-0000-0000-0000-00000000a001', 'concept', 'Концепция: рыба и вино',
     'Мы готовим рыбу так, как её готовят дома в северной Греции: на углях, с лимоном, оливковым маслом и орегано, без сложных соусов. Рыбу каждое утро привозит капитан Стелиос из залива Термаикос. Вина — только из Македонии и с греческих островов.', true),
    ('00000000-0000-0000-0000-00000000d017', '00000000-0000-0000-0000-00000000a001', 'concept', 'Угли и гриль',
     'Гриль у нас только на древесных углях из оливы и дуба, газа на кухне нет. Угли разжигают в полдень, за час до открытия, чтобы к первому гостю они стали ровными и белыми. Рыбу шеф переворачивает один раз — так кожа получается хрустящей, а мясо сочным.', true),
    ('00000000-0000-0000-0000-00000000d018', '00000000-0000-0000-0000-00000000a001', 'concept', 'Оливковое масло',
     'Масло нам привозит семья Карагианни с Халкидики, бочками по двести литров. Им заправляют салаты, поливают рыбу и макают хлеб. Бутылку того же масла можно купить с собой у бара — бабушка Деспина считает, что это лучший сувенир из Салоник.', true),
    ('00000000-0000-0000-0000-00000000d019', '00000000-0000-0000-0000-00000000a001', 'concept', 'Хлеб',
     'Хлеб печём сами из закваски, которой больше двадцати лет — её привезла бабушка Деспина из своей деревни. Хлеб подают к столу бесплатно, тёплым, с оливковым маслом. Хлеб без глютена мы не печём.', true),
    ('00000000-0000-0000-0000-00000000d020', '00000000-0000-0000-0000-00000000a001', 'concept', 'Рыба целиком и цена за вес',
     'Крупную рыбу мы подаём целиком: так она сочнее и честнее. Часть рыбы в меню продаётся по весу — официант принесёт рыбу показать до готовки и назовёт точную цену. Разделать рыбу за столом и убрать кости можно бесплатно, просто попросите.', true),
    ('00000000-0000-0000-0000-00000000d021', '00000000-0000-0000-0000-00000000a001', 'concept', 'Сезонность',
     'Меню меняется вместе с морем и рынком. Какая-то рыба бывает только в сезон, поэтому позиция может временно исчезнуть или оказаться в стоп-листе. Это не каприз шефа, а уважение к улову капитана Стелиоса.', true),
    ('00000000-0000-0000-0000-00000000d022', '00000000-0000-0000-0000-00000000a001', 'collection', 'Подборка «Лёгкое и рыбное»',
     'Если хочется поесть без тяжести: блюда с небольшим количеством жира и большим количеством белка, без фритюра и без мучного. Рыба и морепродукты с гриля, лёгкие закуски. Бабушка Деспина называет этот набор «чтобы потом ещё потанцевать».', true),
    ('00000000-0000-0000-0000-00000000d023', '00000000-0000-0000-0000-00000000a001', 'collection', 'С детьми',
     'Есть детские стульчики и половинные порции рыбы на гриле — попросите официанта. В этой подборке то, что дети обычно едят без уговоров. А ещё дети очень любят смотреть, как официант выносит рыбку коту Порто. Отдельного детского меню и игровой комнаты нет.', true),
    ('00000000-0000-0000-0000-00000000d024', '00000000-0000-0000-0000-00000000a001', 'collection', 'Без мяса и рыбы',
     'Для вегетарианцев: блюда без мяса и рыбы — овощи, бобовые, сыр и хлеб. Шеф Тасос немного грустит, когда гость не ест рыбу, но гемиста у него отличная — бабушка Деспина ставит ей «можно жениться».', true),
    ('00000000-0000-0000-0000-00000000d025', '00000000-0000-0000-0000-00000000a001', 'collection', 'Постное меню',
     'В пост в Греции не едят мясо, молочное и яйца, но можно морепродукты без крови — осьминога, кальмаров, мидии. В подборке — блюда, которые подходят к посту. Во время Великого поста шеф добавляет отдельные постные блюда дня.', true),
    ('00000000-0000-0000-0000-00000000d026', '00000000-0000-0000-0000-00000000a001', 'collection', 'Первый раз у нас: что заказать',
     'Если вы впервые в Лавраки, начните с лавраки на гриле — рыбы, давшей нам имя. К ней — пара закусок, бокал греческого белого и салоникский десерт. Это маршрут, который братья Яннис и Костас советуют всем друзьям, и это единственное, в чём они согласны.', true),
    ('00000000-0000-0000-0000-00000000d027', '00000000-0000-0000-0000-00000000a001', 'collection', 'Мезе на компанию',
     'Греки едят мезе вместе: всё ставят в центр стола и пробуют понемногу. На компанию из четырёх человек советуем пять-шесть мезе, а к ним по рюмке ципуро. Это не закуска перед ужином — это и есть ужин.', true),
    ('00000000-0000-0000-0000-00000000d028', '00000000-0000-0000-0000-00000000a001', 'collection', 'Сытно и по-домашнему',
     'Для тех, кто пришёл очень голодным: мясные блюда по-домашнему. Порции большие, бабушка Деспина накладывает их «как внуку». Если после этого останется место — есть сладкое.', true),
    ('00000000-0000-0000-0000-00000000d029', '00000000-0000-0000-0000-00000000a001', 'collection', 'Недорого и вкусно',
     'Поужинать у нас можно и без дорогой рыбы. Рыба рыбаков, бобовые, салат и домашний напиток. Такой ужин выходит дешевле одной дорады, а капитан Стелиос говорит, что сардину любит больше всего.', true),
    ('00000000-0000-0000-0000-00000000d030', '00000000-0000-0000-0000-00000000a001', 'collection', 'Для сладкоежек',
     'Десерты Нефели: слоёное, сиропное, медовое и один десерт, придуманный стажёром Мильтосом. Самый лёгкий из них — йогурт, самый салоникский — бугаца.', true),
    ('00000000-0000-0000-0000-00000000d031', '00000000-0000-0000-0000-00000000a001', 'collection', 'Ужин вдвоём',
     'Для свидания советуем столик на веранде на закате, одну большую рыбу на двоих с разделкой за столом и бутылку ароматного белого. Ефросинья подберёт вино по тому, как вы держите меню, а Порто — по традиции — сядет рядом и сделает вид, что он тут случайно.', true),
    ('00000000-0000-0000-0000-00000000d032', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Вино к рыбе',
     'К рыбе на гриле и морепродуктам советуем белое ассиртико с Санторини: сухое, с минеральностью и кислотностью. Если хочется ароматнее — малагузия из Эпаноми с нотами персика. Тем, кто любит красное, подойдёт ксиномавро из Наусы — оно лёгкое и хорошо идёт с осьминогом.', true),
    ('00000000-0000-0000-0000-00000000d033', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Вино к мясу',
     'К мусаке, сувлаки и кефтедес лучше всего красное ксиномавро из Наусы: танинное, с нотами вяленых томатов и оливок. Ефросинья называет его «греческим ответом на бароло» и обижается, если гость просит к мясу белое.', true),
    ('00000000-0000-0000-0000-00000000d034', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Наша винная карта',
     'В карте около сорока вин, все греческие: Македония (Науса, Аминдео, Эпаноми, Драма) и острова (Санторини, Крит). Часть вин есть бокалами по 150 мл — ассиртико, малагузия, ксиномавро. Остальное — бутылками, Ефросинья расскажет о каждой.', true),
    ('00000000-0000-0000-0000-00000000d035', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Ципуро и узо',
     'Ципуро — крепкий виноградный дистиллят северной Греции, бывает с анисом и без. Его пьют маленькими рюмками к мезе и никогда не пьют без закуски — так говорит бабушка Деспина, и спорить с ней не принято. Узо тоже есть, но в Салониках принято ципуро.', true),
    ('00000000-0000-0000-0000-00000000d036', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Без алкоголя',
     'Без алкоголя есть домашний лимонад из лимонов Халкидики с мятой и мёдом, греческий горный чай, свежевыжатый апельсиновый сок и холодный фраппе. Безалкогольного вина нет.', true),
    ('00000000-0000-0000-0000-00000000d037', '00000000-0000-0000-0000-00000000a001', 'drinks', 'Кофе',
     'Варим греческий кофе в медной турке на песке: скетто — без сахара, метрио — средний, глико — сладкий. Есть фреддо эспрессо и фраппе. Бабушка Деспина гадает на кофейной гуще, но только своим и только по воскресеньям.', true),
    ('00000000-0000-0000-0000-00000000d038', '00000000-0000-0000-0000-00000000a001', 'event', 'Живая музыка по пятницам',
     'Каждую пятницу с 21:00 у нас играют ребетику и бузуки. Шеф Тасос в эти вечера бьёт в сковороду в такт, а Порто уходит спать подальше — на навес соседнего дома. На пятницу лучше бронировать стол заранее.', true),
    ('00000000-0000-0000-0000-00000000d039', '00000000-0000-0000-0000-00000000a001', 'event', 'Вечер молодого вина',
     'В последнюю субботу каждого месяца — вечер молодого вина: Ефросинья открывает вина урожая этого года от маленьких виноделен Македонии, а дегустация трёх вин стоит 15 €. Начало в 19:00, бронирование обязательно.', true),
    ('00000000-0000-0000-0000-00000000d040', '00000000-0000-0000-0000-00000000a001', 'event', 'Ужин с виноделом',
     'Раз в квартал приглашаем винодела из Македонии: сет из пяти блюд шефа Тасоса и пять вин гостя-винодела, который сам рассказывает о каждом. Стоимость — 65 € с человека, мест двадцать четыре, только по предварительной записи.', true),
    ('00000000-0000-0000-0000-00000000d041', '00000000-0000-0000-0000-00000000a001', 'event', 'Мастер-класс «Рыба на углях»',
     'По воскресеньям в 11:00, до открытия, шеф Тасос учит жарить рыбу на углях: как выбрать рыбу, как развести угли и почему переворачивать только один раз. Группа до восьми человек, 40 € с человека, рыбу съедаете сами. Порто приходит посмотреть, но его не пускают ближе веранды.', true),
    ('00000000-0000-0000-0000-00000000d042', '00000000-0000-0000-0000-00000000a001', 'event', 'Мастер-класс по бугаце',
     'Раз в месяц по субботам в 11:00 Нефели учит тянуть тесто фило и печь бугацу. Предупреждаем: тесто до размеров простыни с первого раза не растягивается ни у кого. Группа до шести человек, 35 € с человека, подходит детям от десяти лет со взрослым.', true),
    ('00000000-0000-0000-0000-00000000d043', '00000000-0000-0000-0000-00000000a001', 'event', 'Греческая Пасха',
     'На православную Пасху мы работаем по особому расписанию и готовим праздничный обед: ягнёнок на вертеле, магирица, красные яйца. В пасхальное воскресенье — только сет-меню по предварительной брони, обычного меню в этот день нет.', true),
    ('00000000-0000-0000-0000-00000000d044', '00000000-0000-0000-0000-00000000a001', 'event', 'Новый год',
     '31 декабря работаем с 20:00 до 03:00 с праздничным сет-меню, живой музыкой и василопитой — новогодним пирогом с монеткой. Кому достанется монетка, тому весь год везёт; в прошлом году она досталась Мильтосу, и он не разбил ни одной тарелки до февраля. Бронирование с 1 ноября.', true),
    ('00000000-0000-0000-0000-00000000d045', '00000000-0000-0000-0000-00000000a001', 'event', 'Апокриес — карнавал',
     'В последние выходные перед Великим постом у нас карнавал Апокриес: гости в костюмах получают бокал ципуро от заведения, а официанты обслуживают в масках. Шеф Тасос каждый год наряжается капитаном Стелиосом, а капитан Стелиос — шефом Тасосом.', true),
    ('00000000-0000-0000-0000-00000000d046', '00000000-0000-0000-0000-00000000a001', 'service', 'Банкеты и праздники',
     '## Зал для праздников
Для праздников есть отдельный зал «Солеварня» на 30 человек и веранда на 50. Весь ресторан можно закрыть под мероприятие до 90 гостей.

## Меню и условия
Банкетное меню — сет на выбор от 35 € с человека, обсуждается с шефом Тасосом. Предоплата — 30%, бронь банкета — минимум за неделю. Свой торт можно принести без сбора.

## Как заказать
Оставьте заявку менеджеру через бота — кнопка «Связаться с менеджером» — или позвоните. Менеджер перезвонит и всё обсудит.', true),
    ('00000000-0000-0000-0000-00000000d047', '00000000-0000-0000-0000-00000000a001', 'service', 'Веранда',
     'Веранда открыта с апреля по октябрь, в остальное время — по погоде, под навесом с обогревателями. На веранде можно с собаками и можно курить в отдельной зоне. Там же живёт кот Порто. Столы на веранде на закате разбирают первыми — бронируйте заранее.', true),
    ('00000000-0000-0000-0000-00000000d048', '00000000-0000-0000-0000-00000000a001', 'service', 'Доставка и с собой',
     'Доставки у нас нет: шеф Тасос считает, что рыба на углях не переживает поездку в коробке. Еду с собой забрать можно — позвоните за 30 минут, упакуем. Рыбу с собой упаковываем целиком, без разделки.', true),
    ('00000000-0000-0000-0000-00000000d049', '00000000-0000-0000-0000-00000000a001', 'service', 'Оплата и чаевые',
     'Принимаем наличные и банковские карты, включая бесконтактную оплату. Счёт можно разделить на компанию. Чаевые не включены в счёт и остаются на ваше усмотрение; всё, что оставлено в банке с рисунком кота, отдаём в приют для кошек.', true),
    ('00000000-0000-0000-0000-00000000d050', '00000000-0000-0000-0000-00000000a001', 'service', 'Подарочные сертификаты',
     'Сертификаты номиналом 50, 100 и 200 € продаются у бара. Сертификат действует год, его можно потратить частями. Можно подарить и мастер-класс шефа Тасоса или Нефели — такие сертификаты оформляет менеджер.', true),
    ('00000000-0000-0000-0000-00000000d051', '00000000-0000-0000-0000-00000000a001', 'service', 'Бронь и опоздания',
     'Стол можно забронировать через бота, бронь подтверждает менеджер. Стол держим 15 минут; если опаздываете, напишите — подождём дольше, если есть возможность. Компаниям больше 20 человек — только через менеджера, а иногда с предоплатой.', true),
    ('00000000-0000-0000-0000-00000000d052', '00000000-0000-0000-0000-00000000a001', 'service', 'Доступность',
     'Вход в зал — с улицы без ступенек, на веранду ведёт пандус. Туалет для гостей на креслах-колясках есть на первом этаже. Зал «Солеварня» на втором этаже, лифта нет.', true),
    ('00000000-0000-0000-0000-00000000d053', '00000000-0000-0000-0000-00000000a001', 'service', 'Дресс-код',
     'Дресс-кода нет: приходите в чём удобно, хоть в шортах после пляжа. Единственный, кто у нас одевается строго, — Порто: он всегда в рыжем.', true),
    ('00000000-0000-0000-0000-00000000d054', '00000000-0000-0000-0000-00000000a001', 'service', 'Если у вас аллергия',
     'Аллергены указаны в карточках блюд, но на кухне все готовят рядом, и следы орехов, глютена, рыбы и молока могут быть в любом блюде. Если аллергия серьёзная, обязательно скажите официанту до заказа — шеф Тасос сам подойдёт и расскажет, что можно.', true),
    ('00000000-0000-0000-0000-00000000d055', '00000000-0000-0000-0000-00000000a001', 'service', 'Как добраться',
     'Мы в квартале Лададика, улица Мициали, 7, в пяти минутах пешком от набережной. Своей парковки нет, ближайшая платная — на улице Эгнатия. Удобнее всего приехать на такси или прийти пешком от порта — заодно увидите лодку «Упрямая Мария».', true),
    ('00000000-0000-0000-0000-00000000d056', '00000000-0000-0000-0000-00000000a001', 'season', 'Летнее меню',
     'С июня по август в меню больше холодного: арбуз с фетой, холодный суп из томатов, сардины и барабулька в сезон. Веранда работает до последнего гостя, а Порто переезжает спать в тень под барной стойкой на веранде.', true),
    ('00000000-0000-0000-0000-00000000d057', '00000000-0000-0000-0000-00000000a001', 'season', 'Осень и сбор винограда',
     'В сентябре и октябре шеф Тасос готовит блюда с молодым виноградом и инжиром, а Ефросинья ездит на сбор винограда в Наусу и возвращается с новыми винами. Первое вино нового урожая открываем на вечере молодого вина в последнюю субботу октября.', true),
    ('00000000-0000-0000-0000-00000000d058', '00000000-0000-0000-0000-00000000a001', 'season', 'Зимнее меню',
     'Зимой в меню появляются супы и тушёные блюда: какавья, фасолада, осьминог с макаронами. Бабушка Деспина говорит, что зимой рыба должна согревать, а не охлаждать. Веранда закрыта или работает под обогревателями.', true),
    ('00000000-0000-0000-0000-00000000d059', '00000000-0000-0000-0000-00000000a001', 'season', 'Календарь рыбы',
     'Барабулька и сардины лучше всего летом, дорада и лавраки — круглый год, осьминог вкуснее зимой. Если какой-то рыбы сейчас нет в продаже, значит, у капитана Стелиоса не сезон, а не у нас лень. Рыба дня зависит от улова и объявляется официантом.', true);

